/* Plain-language definitions. full expands acronyms; learn is the primary
 * local lesson, link an optional external reference. Keys are stable anchors. */
(function () {
  "use strict";
  var WGSM = window.WGSM;
  WGSM.v2terms = WGSM.v2terms || {};
  var terms = {
    ubam: { term: "uBAM", full: "Unaligned BAM", aliases: ["unaligned BAM"],
      short: "A BAM file storing raw sequencing reads before they have been placed onto a reference genome.",
      more: "Keeping reads in a queryname-sorted uBAM preserves instrument metadata and base-modification tags that plain FASTQ conversion strips away.", learn: "learn-files.html#bam" },
    multiqc: { term: "MultiQC", full: "Multi-sample quality control", aliases: [],
      short: "Combines summary logs from tools such as FastQC, samtools and bcftools into a single HTML quality report.",
      more: "MultiQC formats statistics that earlier steps already computed so you can scan read depth, duplication and quality trends in one place.", learn: "learn-sequencing.html#quality" },
    gerp: { term: "GERP++", full: "Genomic Evolutionary Rate Profiling", aliases: ["GERP", "GERP++ conservation"],
      short: "Measures how strongly evolution has preserved a DNA position across aligned mammal and vertebrate genomes.",
      more: "Positive rejected-substitution scores point to conserved bases where past mutations were weeded out over evolutionary time, though benign human variants still appear at conserved sites.", learn: "learn-health.html#scores" },
    phylop: { term: "phyloP", full: "Phylogenetic p-value", aliases: ["PhyloP", "phyloP conservation"],
      short: "Scores whether a single base has evolved more slowly or faster than neutral drift across related species.",
      more: "Positive values mark conserved positions and negative values mark fast-evolving ones, providing one evolutionary clue among many during variant review.", learn: "learn-health.html#scores" },
    pharmgkb: { term: "PharmGKB", full: "Pharmacogenomics Knowledgebase", aliases: [],
      short: "Public database cataloguing published links between human gene variants and medication response.",
      more: "Clinical prescribing weighs full star-allele calls alongside organ function, age and interacting drugs, so review any hit with a physician or pharmacist.", learn: "learn-health.html#medicines" },
    pod5: { term: "POD5", aliases: ["POD5 signal"],
      short: "Oxford Nanopore container format for raw electrical pore-current measurements and run metadata.",
      more: "Keeping POD5 files lets you re-run basecalling later with newer Dorado models or extract methylation tags that standard FASTQ files drop.", learn: "learn-sequencing.html#platforms" },
    dorado: { term: "Dorado", aliases: [],
      short: "Oxford Nanopore basecaller that translates raw electrical POD5 signal into DNA reads and optional methylation tags.",
      more: "Runs best on a supported GPU with a model matched to the flow-cell chemistry; downloading a public model file sends zero sample data over the network.", learn: "learn-sequencing.html#platforms" },
    iupac: { term: "IUPAC", full: "International Union of Pure and Applied Chemistry", aliases: ["IUPAC codes"],
      short: "Standard single-letter codes representing two or more possible DNA bases at one position.",
      more: "For example, R stands for A or G, letting a consensus FASTA record a heterozygous SNP in one string without indicating which parent contributed which letter.", learn: "learn-variants.html#genotype" },
    readgroup: { term: "Read group", aliases: ["read group", "read groups"],
      short: "Header tag marking reads that came from the same library preparation and sequencing lane.",
      more: "Preserving read groups when merging runs lets callers model lane-specific error rates while keeping all reads under one person’s sample name.", learn: "learn-files.html#bam" },
    adaptive: { term: "Adaptive sampling", aliases: ["adaptive sampling"],
      short: "Live Nanopore mode that keeps DNA molecules matching target regions and ejects off-target strands from the pore.",
      more: "A BED file supplies target coordinates (plus flanking padding) to MinKNOW before a live sequencing run starts.", learn: "learn-sequencing.html#platforms" },
    gff3: { term: "GFF3", full: "General Feature Format version 3", aliases: [],
      short: "Tab-separated reference file listing where genes, exons and transcripts sit along each chromosome.",
      more: "Annotation tools pair a GFF3 release with its matching genome build to work out how sample variants overlap known transcripts.", learn: "learn-health.html#annotation" },
    modtags: { term: "MM/ML tags", full: "Base modifications / modification probabilities", aliases: ["MM/ML"],
      short: "Standard SAM, BAM and CRAM tags recording modified bases such as 5-methylcytosine alongside per-site probabilities.",
      more: "Long-read basecallers write MM and ML tags directly into unaligned BAM files; converting reads to ordinary FASTQ discards them.", learn: "learn-sequencing.html#platforms" },
    fastvep: { term: "fastVEP", aliases: [],
      short: "Local research engine pairing variant annotations with automated ACMG/AMP rule checks.",
      more: "Separate from Ensembl VEP and vep-rs; expects GRCh38 vep-rs input and matching reference tables to generate research candidate flags rather than clinical sign-off.", learn: "learn-health.html#annotation" },
    dna: { term: "DNA", full: "Deoxyribonucleic acid", aliases: [],
      short: "Double-stranded molecule inside cells that carries inherited instructions written in four chemical bases: A, C, G and T.",
      more: "Sequencing reads the order of those bases along chromosomes and mitochondrial loops so software can compare them against reference assemblies.", learn: "learn-dna.html#dna" },
    genome: { term: "Genome", aliases: ["genome", "genomes", "whole genome"],
      short: "All the DNA carried in one cell, spanning chromosomes 1–22, sex chromosomes and mitochondrial DNA.",
      more: "One copy of the human nuclear genome runs about 3.1 billion base pairs; typical short-read whole-genome runs cover roughly 90–95% of it cleanly and struggle mainly inside long repeats.", learn: "learn-dna.html#chromosomes" },
    chromosome: { term: "Chromosome", aliases: ["chromosome", "chromosomes", "autosomes", "autosomal"],
      short: "Long packaged DNA molecule inside the cell nucleus: humans typically carry pairs 1–22 (autosomes) plus X and Y.",
      more: "One copy of each autosome comes from each parent, while sex-chromosome copy number varies across individuals and determines ploidy rules during variant calling.", learn: "learn-dna.html#chromosomes" },
    gene: { term: "Gene", aliases: ["gene", "genes"],
      short: "Stretch of DNA transcribed into a functional RNA molecule, often serving as the recipe for a protein.",
      more: "Humans have around 20,000 protein-coding genes whose exons cover under 2% of the genome, and plenty of variants inside genes leave protein function unchanged.", learn: "learn-dna.html#genes" },
    allele: { term: "Allele", aliases: ["allele", "alleles"],
      short: "One specific sequence version observed at a genomic site, such as carrying G where the reference assembly has A.",
      more: "At two-copy autosomal positions your genotype combines two alleles; the reference allele is simply whichever version sat in the donor assembly, and many alternate alleles are the global majority.", learn: "learn-variants.html#genotype" },
    vcf: { term: "VCF", full: "Variant Call Format", aliases: ["VCFs", "variant call format"],
      short: "Tabular text file listing chromosome positions where a sample differs from the reference genome along with called genotypes.",
      more: "A compressed whole-genome small-variant VCF is roughly 100–300 MB and omits raw reads, so any position absent from a variant-only VCF could be reference, unread or filtered out.", learn: "learn-files.html#vcf",
      link: "https://samtools.github.io/hts-specs/VCFv4.5.pdf" },
    gvcf: { term: "gVCF", full: "Genomic Variant Call Format", aliases: ["gVCFs", "genome VCF", "genomic VCF"],
      short: "Extended VCF that records confidence blocks across non-variant stretches alongside variant rows.",
      more: "Lets downstream tools tell a well-covered reference site apart from a coverage dropout and supports joint genotyping across family members.", learn: "learn-files.html#vcf" },
    bam: { term: "BAM", full: "Binary Alignment Map", aliases: ["BAMs", "BAM file"],
      short: "Compressed binary file holding every sequencing read, its base quality scores and where it aligned on a reference.",
      more: "A 30× human genome occupies roughly 60–100 GB; keep its companion .bai or .csi index beside it so tools can jump straight to individual genes.", learn: "learn-files.html#bam" },
    cram: { term: "CRAM", full: "Compressed Reference-oriented Alignment Map", aliases: ["CRAMs", "CRAM file"],
      short: "Compact alignment file that stores read differences against a specific reference genome instead of repeating matching bases.",
      more: "Shrinks a 30× human genome to roughly 15–35 GB; keep its .crai index and record the exact reference FASTA bundle required to decode the reads.", learn: "learn-files.html#bam",
      link: "https://samtools.github.io/hts-specs/CRAMv3.pdf" },
    fastq: { term: "FASTQ", full: "FASTA with Quality scores", aliases: ["FASTQs", "FASTQ file", "fastq.gz"],
      short: "Compressed text file direct from basecalling with four lines per read: identifier, DNA bases, separator and quality string.",
      more: "Paired-end short-read runs arrive as matching R1 and R2 files (~35–45 GB each at 30×) with zero chromosome coordinates until aligned.", learn: "learn-files.html#fastq" },
    fasta: { term: "FASTA", full: "FAST-All (sequence format name)", aliases: [".fa", ".fasta"],
      short: "Plain sequence file starting each chromosome or contig with a >name header line followed by DNA, RNA or protein letters.",
      more: "An uncompressed human reference FASTA is roughly 3 GB; when exported as a personal consensus sequence, FASTA drops per-base quality scores and read depth.", learn: "learn-files.html#reference" },
    index: { term: "Index", aliases: ["index", "indexes", "indexed", ".bai", ".crai", ".tbi", ".csi", ".fai"],
      short: "Small companion file (.bai, .crai, .tbi, .csi or .fai) mapping chromosome coordinates to byte offsets inside a data file.",
      more: "Lets WGS Extract slice out a single gene in seconds without scanning 80 GB end to end; distinct from the multi-gigabyte reference indexes built for aligners.", learn: "learn-files.html#indexes" },
    bed: { term: "BED", full: "Browser Extensible Data", aliases: ["BED file", "BED files"],
      short: "Simple tab-separated table of chromosome, start and end columns defining genomic intervals.",
      more: "Uses zero-based start coordinates and half-open ends (so 0 to 100 covers bases 1 through 100 in one-based VCF numbering) on a specific genome build.", learn: "learn-reference.html#coordinates" },
    kit: { term: "DNA-test file", aliases: ["DNA-test files", "raw data", "raw-data file", "raw-data files", "kit", "kits", "23andMe", "AncestryDNA"],
      short: "Downloadable text table of 600,000 to 700,000 selected marker genotypes from a consumer microarray test or WGS export.",
      more: "Useful (~15–30 MB) for cousin matching and ancestry calculators, while leaving the other 99.98% of the genome untested.", learn: "learn-files.html#kits" },
    chip: { term: "Microarray", aliases: ["chip", "chips", "microarray", "microarrays"],
      short: "Glass or silicon slide coated with DNA probes that test a fixed list of hundreds of thousands of known SNPs.",
      more: "Standard technology behind 23andMe and AncestryDNA kits; probes report only pre-selected positions and miss novel or rare variants elsewhere in the same gene.", learn: "learn-sequencing.html#sample" },
    marker: { term: "Marker", aliases: ["marker", "markers"],
      short: "Catalogued DNA site or repeat motif compared across samples in ancestry panels, kits or lineage trees.",
      more: "Different consumer chip versions measure only partially overlapping marker lists, capping how many sites two exported kits can compare.", learn: "learn-ancestry.html#autosomal" },
    rsid: { term: "rsID", full: "Reference SNP cluster identifier", aliases: ["rsIDs"],
      short: "Accession tag such as rs429358 assigned by the public dbSNP catalogue to a known variable locus.",
      more: "Names the genomic spot rather than one specific allele: a single rsID can cover several alternate letters, and its numeric coordinate moves between GRCh37 and GRCh38.", learn: "learn-variants.html#types" },
    strand: { term: "Strand", aliases: ["strand", "strands", "strand-ambiguous"],
      short: "Either chain of the DNA double helix, paired across the rung so A faces T and C faces G.",
      more: "Reference FASTAs report the forward strand while some microarray exports flip conventions; A/T and C/G SNPs require strand metadata to orient safely.", learn: "learn-dna.html#dna" },
    reference: { term: "Reference genome", aliases: ["reference genome", "reference genomes", "reference sequence"],
      short: "Standardized assembly of chromosome sequences giving labs and tools a shared coordinate system.",
      more: "Built from a mosaic of volunteer donors rather than representing an ideal genome; CRAM files depend on matching the exact reference FASTA used during compression.", learn: "learn-reference.html#reference",
      link: "https://www.ncbi.nlm.nih.gov/grc/human" },
    build: { term: "Genome build", aliases: ["genome build", "genome builds", "builds of the reference"],
      short: "Numbered release of a reference genome assembly, such as GRCh37, GRCh38 or T2T-CHM13.",
      more: "Closing gaps between builds shifts millions of coordinates downstream; verify both build and contig naming before comparing two files.", learn: "learn-reference.html#builds" },
    grch37: { term: "GRCh37", full: "Genome Reference Consortium human build 37", aliases: ["hg19", "build 37"],
      short: "2009 human reference assembly still common in older BAM archives and consumer microarray exports.",
      more: "Shares primary autosomal coordinates with UCSC hg19 while differing in chromosome prefixes (1 vs chr1) and early mitochondrial sequence.", learn: "learn-reference.html#builds" },
    grch38: { term: "GRCh38", full: "Genome Reference Consortium human build 38", aliases: ["hg38", "build 38"],
      short: "2013 human reference assembly expected by current clinical databases, callers and annotation pipelines.",
      more: "Closed hundreds of GRCh37 gaps and standardized the mitochondrial ring; check exact bundle names (hs38, hs38d1, hs38DH) because decoy contigs vary.", learn: "learn-reference.html#builds" },
    hs37d5: { term: "hs37d5", full: "Human sequence, build 37 with decoy sequences", aliases: [],
      short: "1000 Genomes GRCh37 reference FASTA augmented with viral and decoy sequences to catch stray short reads.",
      more: "Required intact whenever decoding a CRAM compressed against hs37d5, since plain hg19 FASTA files lack its extra contigs.", learn: "learn-reference.html#cram" },
    hs38: { term: "hs38", full: "Human sequence, build 38 reference bundle", aliases: ["hs38d1", "hs38DH"],
      short: "Family of GRCh38 reference FASTA bundles where suffixes like d1 and DH mark added decoy or HLA sequences.",
      more: "Primary chromosomes 1–22 share coordinates across bundles, yet CRAM checksums verify every contig in the header before decoding reads.", learn: "learn-reference.html#cram" },
    t2t: { term: "T2T-CHM13", full: "Telomere-to-Telomere CHM13 assembly", aliases: ["T2T", "CHM13", "T2T-CHM13 v2.0"],
      short: "2022 human assembly that finished centromeres and long repeat arrays gap-free from telomere to telomere.",
      more: "Because the CHM13 cell line carried two X chromosomes, full human bundles add a finished Y chromosome from donor HG002; coordinates differ from GRCh38.", learn: "learn-reference.html#builds",
      link: "https://github.com/marbl/CHM13" },
    decoy: { term: "Decoy", aliases: ["decoy", "decoys", "decoy sequences"],
      short: "Extra human and viral sequences appended to a reference FASTA so off-assembly reads land cleanly.",
      more: "Prevents repetitive or Epstein-Barr virus reads from being forced onto chromosomes 1–22 where they would trigger false variant calls.", learn: "learn-reference.html#cram" },
    reads: { term: "Read", aliases: ["reads", "raw reads", "short reads", "sequencing reads"],
      short: "Sequence of bases read from a single DNA fragment by a sequencing instrument, paired with per-base quality scores.",
      more: "Illumina runs typically produce hundreds of millions of 150 bp reads; callers stack overlapping reads at each position so sporadic miscalls wash out.", learn: "learn-sequencing.html#reads" },
    paired: { term: "Paired-end", aliases: ["paired-end", "paired reads", "read pairs"],
      short: "Sequencing both ends of a ~300–500 bp DNA fragment to produce two linked reads (R1 and R2) at a roughly known spacing.",
      more: "Keep R1 and R2 files matched from the same run; knowing the gap between mates helps aligners anchor reads across short repetitive stretches.", learn: "learn-sequencing.html#reads" },
    bp: { term: "bp", full: "Base pair", aliases: ["base pair", "base pairs"],
      short: "One paired rung on the DNA double helix, used as the standard unit of sequence length.",
      more: "1 kb equals 1,000 bp and 1 Mb equals one million bp; a 2 × 150 bp Illumina run reads 150 bases inward from each end of a longer DNA fragment.", learn: "learn-dna.html#dna" },
    illumina: { term: "Illumina", aliases: [],
      short: "Widely used short-read sequencing technology that images fluorescently tagged bases across hundreds of millions of DNA clusters.",
      more: "Delivers low per-base error rates on 100–150 bp paired reads at low cost, while struggling inside repeats longer than a single fragment.", learn: "learn-sequencing.html#platforms" },
    longreads: { term: "Long reads", aliases: ["long reads", "long read", "long-read"],
      short: "Single-molecule sequencing reads spanning thousands to tens of thousands of bases in one unbroken piece.",
      more: "Long reads cross repetitive regions, structural rearrangements and distant variant pairs directly; choose caller models built for either PacBio HiFi or Nanopore.", learn: "learn-sequencing.html#platforms" },
    pacbio: { term: "PacBio HiFi", full: "Pacific Biosciences High-Fidelity reads", aliases: ["PacBio", "HiFi"],
      short: "Long, high-accuracy reads (~10–25 kb) generated by reading the same circularized DNA molecule many times in a row.",
      more: "Combines near-Illumina base accuracy with multi-kilobase reach for phasing and structural variants when paired with HiFi-aware aligners and callers.", learn: "learn-sequencing.html#platforms" },
    ont: { term: "ONT", full: "Oxford Nanopore Technologies", aliases: ["Oxford Nanopore", "Nanopore", "nanopore"],
      short: "Single-molecule sequencing that infers DNA bases and chemical modifications from electrical current changes across protein pores.",
      more: "Reads routinely reach tens of kilobases or longer; accuracy and methylation tags depend on flow-cell chemistry and the Dorado basecalling model used.", learn: "learn-sequencing.html#platforms" },
    align: { term: "Alignment", aliases: ["align", "aligned", "aligning", "alignment", "realign", "realigned", "realigning"],
      short: "Matching millions of raw reads onto their most likely chromosome coordinates along a reference genome.",
      more: "Converts unplaced FASTQ reads into sorted BAM or CRAM records over several hours of CPU work, flagging ambiguous repeat hits with low mapping quality.", learn: "learn-files.html#alignment" },
    bwa: { term: "bwa", full: "Burrows-Wheeler Aligner", aliases: ["BWA", "BWA-MEM", "bwa mem"],
      short: "Classic short-read aligner whose BWA-MEM algorithm maps Illumina paired-end reads against a reference index.",
      more: "Expects prebuilt BWA index files matching your chosen reference FASTA; long reads use minimap2 instead.", learn: "learn-files.html#alignment" },
    bwamem2: { term: "bwa-mem2", full: "Burrows-Wheeler Aligner, maximal exact match 2", aliases: [],
      short: "SIMD-accelerated successor to BWA-MEM that produces matching short-read alignments roughly twice as fast on modern CPUs.",
      more: "Requires much larger reference index files on disk and tens of gigabytes of RAM during a whole-genome alignment run.", learn: "learn-files.html#alignment" },
    bwamem3: { term: "bwa-mem3", full: "Burrows-Wheeler Aligner, maximal exact match 3", aliases: [],
      short: "High-throughput short-read aligner supported in WGS Extract that reuses bwa-mem2 reference indexes.",
      more: "Speed and exact tie-breaking depend on CPU instruction support and selected preset options.", learn: "learn-files.html#alignment" },
    minimap2: { term: "minimap2", aliases: [],
      short: "Fast aligner built for mapping PacBio HiFi, Oxford Nanopore and assembled contigs onto a reference genome.",
      more: "Select the preset matching your read chemistry (such as map-hifi or map-ont) so splice and indel penalties fit the data.", learn: "learn-files.html#alignment" },
    depth: { term: "Depth", aliases: ["depth", "mean depth", "coverage", "read depth"],
      short: "How many aligned reads overlap a given base; mean depth (such as 30×) averages that count across the genome.",
      more: "In a 30× genome individual bases often range from 10 to 50 reads, and single-copy X and Y regions in an XY sample average roughly 15×.", learn: "learn-sequencing.html#depth" },
    unmapped: { term: "Unmapped reads", aliases: ["unmapped reads", "unmapped"],
      short: "Sequencing reads retained in a BAM or CRAM without a chromosome coordinate because no clean reference match was found.",
      more: "Usually reflect human centromere or donor sequence absent from the reference, oral bacteria in saliva kits or low-quality read tails.", learn: "learn-sequencing.html#quality" },
    phred: { term: "Phred quality", full: "Phred-scaled error probability", aliases: ["Phred", "base quality", "quality scores", "Q30"],
      short: "Logarithmic confidence scale where Q20 represents a 1-in-100 estimated error chance and Q30 represents 1-in-1,000.",
      more: "Used separately for single-base calls, read placement (MAPQ) and final genotypes (GQ), all derived from instrument or software probability models.", learn: "learn-sequencing.html#quality" },
    mapq: { term: "MAPQ", full: "Mapping quality", aliases: ["mapping quality"],
      short: "Phred-scaled estimate of how confident the aligner is that an entire read belongs at its assigned coordinate.",
      more: "Drops near zero when a read fits two duplicated regions equally well; in SAM/BAM records, a value of 255 marks mapping quality as unavailable.", learn: "learn-sequencing.html#quality" },
    gq: { term: "GQ", full: "Genotype quality", aliases: ["genotype quality", "Genotype quality"],
      short: "Phred-scaled confidence score for the specific allele pair (such as 0/1 vs 1/1) written by a variant caller.",
      more: "GQ 20 corresponds to 99% modeled confidence and GQ 30 to 99.9%; inspect raw reads in IGV too, since misalignment artifacts can still earn high GQ.", learn: "learn-variants.html#confidence" },
    n50: { term: "N50", full: "Length-weighted median sequence length", aliases: ["read N50"],
      short: "Read-length milestone where half of all sequenced bases come from reads at least N50 bases long.",
      more: "A 20 kb read N50 tells you half the run’s coverage sits in 20 kb+ molecules, summarizing fragment reach independently of base accuracy.", learn: "learn-sequencing.html#platforms" },
    variant: { term: "Variant", aliases: ["variant", "variants"],
      short: "Any spot where a sample’s DNA sequence differs from the chosen reference assembly, from a one-base swap to a large deletion.",
      more: "A typical human whole genome carries 4 to 5 million small variants relative to GRCh38, almost all of them ordinary inherited polymorphism.", learn: "learn-variants.html#types" },
    calling: { term: "Variant calling", aliases: ["variant calling", "call variants", "calls variants", "calling variants", "caller", "callers", "variant caller"],
      short: "Analyzing stacked BAM or CRAM reads at each position to distinguish inherited DNA differences from read errors.",
      more: "Outputs VCF or gVCF genotypes using models tuned to the sequencing platform and chromosome ploidy.", learn: "learn-files.html#calling" },
    genotype: { term: "Genotype", aliases: ["genotype", "genotypes"],
      short: "The allele or pair of alleles called for one sample at a genomic site, written as 0/0, 0/1 or 1/1 in VCF files.",
      more: "0 denotes the reference allele, 1 the first alternate allele and . an uncalled allele when read support fell short.", learn: "learn-variants.html#genotype" },
    snp: { term: "SNP", full: "Single-nucleotide polymorphism", aliases: ["SNPs"],
      short: "Single-base position that varies commonly across human populations, accounting for millions of sites per person.",
      more: "Consumer microarray kits test selected SNPs, whereas whole-genome sequencing reads both common SNPs and private single-base variants.", learn: "learn-variants.html#types" },
    snv: { term: "SNV", full: "Single-nucleotide variant", aliases: ["SNVs"],
      short: "Substitution of one DNA letter for another (such as C to T) regardless of how common or rare it is.",
      more: "Covers roughly 4.1 million calls in a typical human whole-genome VCF before frequency or consequence filtering.", learn: "learn-variants.html#types" },
    indel: { term: "Indel", full: "Insertion or deletion", aliases: ["indel", "indels"],
      short: "Addition or loss of a short stretch of DNA bases (conventionally under 50 bp) relative to the reference.",
      more: "Left-align and normalize indels in repetitive motifs before matching against ClinVar or gnomAD so equivalent shifts share the same coordinate.", learn: "learn-variants.html#types" },
    sv: { term: "SV", full: "Structural variant", aliases: ["structural variant", "structural variants", "SVs"],
      short: "Genomic rearrangement spanning roughly 50 bp or more, including deletions, duplications, inversions and translocations.",
      more: "Detected from split reads, discordant read pairs or long reads rather than standard SNP/indel callers like DeepVariant.", learn: "learn-variants.html#types" },
    cnv: { term: "CNV", full: "Copy-number variant", aliases: ["CNVs", "copy-number variant", "copy-number variants", "copy number"],
      short: "Deletion or duplication that leaves a chromosome segment with fewer or more copies than expected.",
      more: "Short-read callers spot CNVs from shifts in local read depth and split breakpoints, though GC-bias waves require careful filtering.", learn: "learn-variants.html#types" },
    str: { term: "STR", full: "Short tandem repeat", aliases: ["STRs", "short tandem repeat", "short tandem repeats", "repeat expansions"],
      short: "Short DNA motif such as CAG repeated back to back, prone to slipping by a unit or two across generations.",
      more: "Expansions beyond 150 bp exceed a single short read’s span, so clinical repeat disorders often need long reads or targeted PCR sizing.", learn: "learn-variants.html#types" },
    ystr: { term: "Y-STR", full: "Y-chromosome short tandem repeat", aliases: ["Y-STRs"],
      short: "Repeated short motif on the Y chromosome whose copy count mutates fast enough for paternal surname genealogy.",
      more: "Dedicated capillary panels measure long Y-STRs more reliably than 150 bp whole-genome reads, which can clip longer repeat arrays.", learn: "learn-ancestry.html#lineage" },
    deepvariant: { term: "DeepVariant", aliases: [],
      short: "Neural-network small-variant caller that scores read pileups to output high-accuracy SNP and indel VCFs.",
      more: "Pick the model trained for your read type (WGS Illumina, PacBio HiFi or ONT); structural variants and repeat expansions still need separate callers.", learn: "learn-files.html#calling" },
    gatk: { term: "GATK", full: "Genome Analysis Toolkit", aliases: ["GATK HaplotypeCaller", "HaplotypeCaller"],
      short: "Broad Institute analysis suite whose HaplotypeCaller reassembles local reads to call SNPs, indels and gVCFs.",
      more: "Widely used for family gVCF joint genotyping when paired with matching reference bundles.", learn: "learn-files.html#calling" },
    bcftools: { term: "bcftools", full: "Binary Call Format tools", aliases: [],
      short: "Fast C toolkit for filtering, merging, normalizing, querying and calling variants in VCF and BCF files.",
      more: "Powers lightweight mpileup variant calling and rapid region or tag queries across indexed VCF archives.", learn: "learn-files.html#calling" },
    samtools: { term: "samtools", full: "Sequence Alignment/Map tools", aliases: [],
      short: "Core command-line suite for sorting, indexing, slicing, viewing and converting SAM, BAM and CRAM alignments.",
      more: "Runs underneath most WGS Extract alignment inspections, coverage summaries and BAM-to-CRAM conversions.", learn: "learn-files.html#indexes" },
    htslib: { term: "htslib", full: "High-throughput sequencing library", aliases: [],
      short: "Shared C library implementing bgzip compression, tabix indexing and BAM, CRAM and VCF parsing.",
      more: "Provides the underlying file-format engine inside samtools, bcftools and many Python or Rust genomics tools.", learn: "learn-files.html#indexes" },
    phasing: { term: "Phasing", aliases: ["phasing", "phase", "phased", "unphased"],
      short: "Assigning heterozygous variants along a chromosome onto the two separate parental copies (written with | instead of /).",
      more: "Long reads can phase nearby variants directly across one DNA molecule, while parent-child trios separate maternal and paternal chromosomes cleanly.", learn: "learn-variants.html#phasing" },
    imputation: { term: "Imputation", aliases: ["imputation", "impute", "imputed", "imputing"],
      short: "Filling in untyped common markers statistically from surrounding haplotypes in a population reference panel.",
      more: "Boosts marker overlap for microarray kits and low-pass genomes, while missing rare or family-private variants absent from the panel.", learn: "learn-variants.html#phasing" },
    denovo: { term: "De novo", aliases: ["de novo"],
      short: "Variant present in a child that arose freshly in a germ cell or early embryo rather than coming from either parent’s genome.",
      more: "Humans average roughly 60–80 true de novo single-base mutations per birth, swamped in raw trio VCFs by hundreds of parent coverage dropouts unless reads are checked.", learn: "learn-variants.html#confidence" },
    heteroplasmy: { term: "Heteroplasmy", aliases: ["heteroplasmy", "heteroplasmic"],
      short: "Carrying two slightly different mitochondrial DNA sequences across the hundreds of mitochondria inside cells.",
      more: "Variant fractions can shift between saliva and blood or across relatives and often appear as benign background variation.", learn: "learn-ancestry.html#lineage" },
    contamination: { term: "Contamination", aliases: ["contamination", "contaminated"],
      short: "Foreign DNA mixed into a sequencing sample, either oral microbes in saliva or stray human DNA from sample handling.",
      more: "Cross-human mixture above 1–2% skews heterozygous allele balances and creates false variant calls; bacterial reads usually stay unmapped.", learn: "learn-sequencing.html#quality" },
    relatedness: { term: "Relatedness", aliases: ["relatedness", "kinship"],
      short: "Measure of inherited autosomal DNA shared between two samples, distinguishing parent-child, sibling and cousin ties.",
      more: "Catches accidental file swaps inside a family library; categories sharing ~25% DNA (grandparent, aunt/uncle, half-sibling) need family context to separate.", learn: "learn-ancestry.html#relatives" },
    ploidy: { term: "Ploidy", aliases: ["ploidy", "diploid", "haploid"],
      short: "Expected chromosome copy count in a region: diploid (two copies) on autosomes versus haploid (one copy) on non-PAR XY regions.",
      more: "Running a diploid caller over single-copy X or Y sequence creates spurious heterozygous calls where misaligned reads collide.", learn: "learn-variants.html#genotype" },
    zygosity: { term: "Zygosity", aliases: ["heterozygous", "homozygous", "heterozygosity", "zygosity"],
      short: "Whether your two copies at a diploid site carry different alleles (heterozygous) or matching alleles (homozygous).",
      more: "Single-copy X or Y loci in XY samples are called hemizygous instead; clinical interpretation pairs zygosity with whether a gene acts dominantly or recessively.", learn: "learn-variants.html#genotype" },
    titv: { term: "Ti/Tv", full: "Transition-to-transversion ratio", aliases: ["transitions to transversions", "transitions", "transversions"],
      short: "Ratio of purine-purine (A↔G) and pyrimidine-pyrimidine (C↔T) swaps to all other single-base substitutions.",
      more: "Human whole-genome call sets typically land near 2.0–2.1 (and ~2.8–3.0 in coding exons), whereas random sequencing noise drifts toward 0.5.", learn: "learn-variants.html#confidence" },
    jointcalling: { term: "Joint calling", aliases: ["joint calling", "joint-called", "joint genotyping"],
      short: "Genotyping multiple family or cohort gVCFs together so every sample receives a call or confidence check at shared sites.",
      more: "Prevents the missing-equals-reference trap when comparing parents and children, provided all gVCFs share one build and caller pipeline.", learn: "learn-files.html#vcf" },
    haplogroup: { term: "Haplogroup", aliases: ["haplogroup", "haplogroups"],
      short: "Named branch on the human Y-DNA or mitochondrial phylogenetic tree defined by shared historical mutations.",
      more: "Traces a single unbroken paternal or maternal line back thousands of years, representing two outer edges of a much wider family tree.", learn: "learn-ancestry.html#lineage",
      link: "https://isogg.org/wiki/Haplogroup" },
    ydna: { term: "Y-DNA", full: "Y-chromosome DNA", aliases: ["Y chromosome", "Y chromosomes"],
      short: "DNA along the male-inherited Y chromosome whose non-recombining region passes virtually intact from father to son.",
      more: "XX samples carry no Y chromosome and can trace their paternal line through a father, brother or paternal uncle’s sample.", learn: "learn-ancestry.html#lineage" },
    mtdna: { term: "mtDNA", full: "Mitochondrial DNA", aliases: ["mitochondrial DNA"],
      short: "Compact 16,569-base circular genome inside cell mitochondria passed from mother to every child.",
      more: "Cells carry hundreds of mtDNA copies, producing thousands-fold read depth alongside occasional nuclear pseudogene (NUMT) read cross-mapping.", learn: "learn-ancestry.html#lineage" },
    admixture: { term: "Ancestry proportions", aliases: ["ancestry proportions", "admixture"],
      short: "Statistical breakdown modeling your autosomal markers as a weighted blend of sampled reference populations.",
      more: "Percentages describe similarity to modern reference panels and shift whenever populations are split, merged or swapped.", learn: "learn-ancestry.html#autosomal" },
    refpop: { term: "Reference populations", aliases: ["reference populations", "reference population"],
      short: "Curated groups of sampled volunteers used as comparison baselines in autosomal ancestry calculators.",
      more: "When an ancestral community is absent from the panel, calculators divide its segments across the closest sampled neighbors.", learn: "learn-ancestry.html#autosomal" },
    kg1000: { term: "1000 Genomes", aliases: ["1000 Genomes Project"],
      short: "Open international catalogue of whole-genome variation across 26 sampled global populations.",
      more: "Phase 3 covers 2,504 unrelated donors and the later 30× NYGC expansion adds family trios to reach 3,202 samples.", learn: "learn-ancestry.html#autosomal" },
    hgdp: { term: "HGDP", full: "Human Genome Diversity Project", aliases: ["Human Genome Diversity Project"],
      short: "Research panel sampling indigenous and historically isolated populations across five continents for diversity studies.",
      more: "Often combined with 1000 Genomes to broaden geographic coverage, though several regions still rely on small sample sizes.", learn: "learn-ancestry.html#autosomal" },
    interval: { term: "95% interval", aliases: ["95% intervals"],
      short: "Range around an estimated percentage showing how much the number wobbles across resampled chromosome blocks.",
      more: "Reflects random sampling spread inside the chosen model while leaving systematic gaps in the reference panel invisible.", learn: "learn-ancestry.html#limits" },
    annotation: { term: "Annotation", aliases: ["annotation", "annotate", "annotated", "annotating"],
      short: "Enriching raw VCF coordinates with gene transcripts, amino-acid changes, gnomAD frequencies and ClinVar records.",
      more: "Labels change with transcript choice and database release without altering the underlying genotype quality.", learn: "learn-health.html#annotation" },
    clinvar: { term: "ClinVar", full: "Clinical Variation database", aliases: [],
      short: "Public NCBI archive gathering variant-condition interpretations submitted by diagnostic labs and researchers.",
      more: "Read the review-star consensus, named disorder, submission dates and inheritance mode together, and confirm medically relevant hits through a clinician.", learn: "learn-health.html#clinvar",
      link: "https://www.ncbi.nlm.nih.gov/clinvar/" },
    vep: { term: "VEP", full: "Ensembl Variant Effect Predictor", aliases: ["Variant Effect Predictor"],
      short: "Ensembl tool that maps VCF variants onto gene transcripts to predict coding, splice and regulatory consequences.",
      more: "Requires a transcript cache matched to your genome build; one DNA variant can carry different consequence labels across alternate transcripts of the same gene.", learn: "learn-health.html#annotation",
      link: "https://www.ensembl.org/info/docs/tools/vep/index.html" },
    gnomad: { term: "gnomAD", full: "Genome Aggregation Database", aliases: [],
      short: "Large public reference cohort reporting variant counts and allele frequencies across hundreds of thousands of exomes and genomes.",
      more: "High gnomAD frequency rules out a variant as a solo cause of a rare severe Mendelian disease, while zero observations is ordinary for benign private variants.", learn: "learn-health.html#frequency",
      link: "https://gnomad.broadinstitute.org/" },
    af: { term: "AF", full: "Allele frequency", aliases: ["allele frequency", "allele frequencies"],
      short: "Share of measured chromosome copies in a cohort carrying a specific allele (0.01 equals 1% of counted copies).",
      more: "Check sample counts and ancestry breakdown alongside the overall fraction, since frequencies can differ sharply across populations.", learn: "learn-health.html#frequency" },
    acmg: { term: "ACMG", full: "American College of Medical Genetics and Genomics", aliases: [],
      short: "Medical genetics college publishing clinical practice guidelines, the Secondary Findings gene list and classification standards.",
      more: "Distinguish its actionable Secondary Findings gene list from the joint ACMG/AMP 28-criteria framework labs use to classify individual variants.", learn: "learn-health.html#clinvar" },
    cadd: { term: "CADD", full: "Combined Annotation Dependent Depletion", aliases: [],
      short: "Genome-wide ranking score combining evolutionary conservation and functional annotations for single-base variants and indels.",
      more: "Scaled CADD 20 places a variant in the top 1% of scored substitutions and 30 in the top 0.1%, ranking candidates for follow-up rather than stating disease probability.", learn: "learn-health.html#scores" },
    revel: { term: "REVEL", full: "Rare Exome Variant Ensemble Learner", aliases: [],
      short: "Ensemble predictor scoring rare missense variants from 0 to 1 by combining thirteen conservation and functional tools.",
      more: "Higher values suggest stronger predicted protein disruption when prioritizing candidate lists alongside population frequency and clinical evidence.", learn: "learn-health.html#scores" },
    spliceai: { term: "SpliceAI", full: "Splice-site Artificial Intelligence model", aliases: [],
      short: "Deep-learning model scoring from 0 to 1 whether a sequence change creates or weakens an RNA splice junction.",
      more: "Flags intronic or synonymous variants that may alter exon splicing, subject to confirmation in RNA or clinical studies.", learn: "learn-health.html#scores" },
    alphamissense: { term: "AlphaMissense", aliases: [],
      short: "Protein-structure model scoring single amino-acid substitutions across the human proteome.",
      more: "Ranks missense candidates using structural context and evolutionary conservation without assessing non-coding, splice or copy-number changes.", learn: "learn-health.html#scores" },
    pgx: { term: "PGx", full: "Pharmacogenomics", aliases: ["pharmacogenomics", "Pharmacogenomics"],
      short: "Study of how inherited variants in enzymes, transporters and immune genes alter response to specific medications.",
      more: "Share any pharmacogenomic output with a physician or pharmacist rather than adjusting doses yourself, as organ function and drug interactions weigh heavily too.", learn: "learn-health.html#medicines" },
    pharmcat: { term: "PharmCAT", full: "Pharmacogenomics Clinical Annotation Tool", aliases: [],
      short: "Software matching sample genotypes against named pharmacogene star alleles and published CPIC prescribing guidelines.",
      more: "Works most reliably when reference-covered gVCF or BAM evidence confirms unmutated defining positions alongside variants.", learn: "learn-health.html#medicines" },
    hla: { term: "HLA", full: "Human leukocyte antigen", aliases: ["HLA typing"],
      short: "Hyper-variable immune-recognition gene cluster on chromosome 6 involved in transplant matching and certain drug reactions.",
      more: "Standard short-read alignments tangle inside HLA exons, so dedicated typing callers and accredited lab verification are required before clinical use.", learn: "learn-health.html#medicines" },
    cyp2d6: { term: "CYP2D6", full: "Cytochrome P450 family 2 subfamily D member 6", aliases: [],
      short: "Liver-enzyme gene involved in metabolizing roughly a fifth of common prescription drugs, including codeine and several antidepressants.",
      more: "Whole-gene deletions, extra copies and hybrids with neighboring pseudogene CYP2D7 require specialized copy-number and structural callers.", learn: "learn-health.html#medicines" },
    missense: { term: "Missense", aliases: ["missense"],
      short: "Coding DNA change that swaps one amino acid for another in the resulting protein chain.",
      more: "Effects span completely harmless substitutions through loss of protein function depending on protein domain and transcript.", learn: "learn-health.html#annotation" },
    pathogenic: { term: "Pathogenic", aliases: ["pathogenic", "likely pathogenic", "benign", "likely benign"],
      short: "Clinical classification meaning strong evidence links a variant to a specific disorder under the relevant inheritance pattern; benign marks evidence against harm.",
      more: "Clinical impact still depends on zygosity (carrier vs two-copy recessive), age-dependent penetrance and verifying the raw read call.", learn: "learn-health.html#clinvar" },
    vus: { term: "VUS", full: "Variant of uncertain significance", aliases: [],
      short: "Clinical classification used when published data are too thin or conflicting to label a variant benign or pathogenic.",
      more: "Medical guidelines treat a VUS as unactionable on its own; labs periodically reclassify VUS entries as larger cohorts are studied.", learn: "learn-health.html#clinvar" },
    staralleles: { term: "Star allele", aliases: ["star alleles", "star allele", "diplotype"],
      short: "Standard haplotype name such as CYP2C19*2 representing a defined bundle of variants on one copy of a pharmacogene; two copies form a diplotype.",
      more: "When defining positions are missing from a variant-only VCF, software can default falsely toward *1 unless coverage is tracked.", learn: "learn-health.html#medicines" },
    pgs: { term: "PGS", full: "Polygenic score", aliases: ["polygenic score", "polygenic scores"],
      short: "Weighted sum across hundreds to millions of common variants associated with a measured trait in genome-wide studies.",
      more: "Places a sample along a comparison distribution; accuracy drops when the individual’s ancestry diverges from the original study cohort.", learn: "learn-health.html#polygenic" },
    prs: { term: "PRS", full: "Polygenic risk score", aliases: [],
      short: "Polygenic score built specifically to summarize common-variant susceptibility toward a complex condition such as coronary disease.",
      more: "Reported percentiles compare genetic ranking against a reference group and need age, clinical measurements and baseline prevalence to estimate actual risk.", learn: "learn-health.html#polygenic" },
    methylation: { term: "Methylation", aliases: ["methylation", "methylated"],
      short: "Chemical methyl tag attached directly to DNA bases (most often cytosines) that helps cells regulate gene activity.",
      more: "Preserved natively by Nanopore POD5/uBAM and PacBio kinetic runs while erased during PCR amplification in standard Illumina libraries; patterns vary by tissue and age.", learn: "learn-sequencing.html#platforms" },
    cpg: { term: "CpG", full: "Cytosine–phosphate–guanine", aliases: ["CpG sites"],
      short: "Cytosine base immediately followed by guanine along the same DNA strand, where human DNA methylation mostly occurs.",
      more: "Written with a lowercase p for the phosphate backbone to distinguish along-strand C-then-G sites from C:G pairs across opposite strands.", learn: "learn-sequencing.html#platforms" },
    m5c: { term: "5mC", full: "5-methylcytosine", aliases: [],
      short: "Cytosine base carrying a methyl group at its fifth carbon ring position, the primary epigenetic mark in human DNA.",
      more: "Modification-aware Nanopore and PacBio basecallers record per-read 5mC probabilities inside BAM MM and ML tags.", learn: "learn-sequencing.html#platforms" },
    igv: { term: "IGV", full: "Integrative Genomics Viewer", aliases: ["genome browser", "Integrative Genomics Viewer"],
      short: "Interactive genome browser for viewing stacked BAM/CRAM reads, base qualities and VCF calls over a gene.",
      more: "Checking an unexpected variant in IGV quickly spots strand bias, soft-clipped repeat artifacts or low-MAPQ pileups.", learn: "learn-variants.html#confidence" },
    gpu: { term: "GPU", full: "Graphics processing unit", aliases: ["GPUs"],
      short: "Parallel processor holding thousands of compute cores suited to neural-network basecalling and DeepVariant.",
      more: "Acceleration depends on matching hardware and API support, as NVIDIA CUDA containers and Apple Metal builds target separate chips.", learn: "learn-files.html#computing" },
    cpu: { term: "CPU", full: "Central processing unit", aliases: ["CPUs", "threads", "cores"],
      short: "Main processor running aligners, sorters and variant callers across parallel worker threads.",
      more: "Adding threads speeds up alignment and calling until RAM bandwidth or SSD read/write throughput becomes the bottleneck.", learn: "learn-files.html#computing" },
    ram: { term: "RAM", full: "Random-access memory", aliases: [],
      short: "Fast volatile working memory holding reference indexes and read buffers while genomics tools execute.",
      more: "Whole-genome bwa-mem2 alignment and sorting routinely require 16–64 GB of RAM; running short forces slow disk swapping or out-of-memory exits.", learn: "learn-files.html#computing" },
    cuda: { term: "CUDA", full: "Compute Unified Device Architecture", aliases: [],
      short: "NVIDIA’s parallel-computing runtime used by GPU builds of Dorado, DeepVariant and Parabricks.",
      more: "Requires a compatible NVIDIA GPU and host driver version; Mac systems with Apple silicon use Metal or CPU builds instead.", learn: "learn-files.html#computing" },
    metal: { term: "Metal", aliases: [],
      short: "Apple’s GPU compute and graphics framework on Apple silicon Macs.",
      more: "Accelerates tools compiled specifically with Metal support, such as Apple-silicon Dorado basecalling.", learn: "learn-files.html#computing" },
    docker: { term: "Docker", aliases: ["container", "containers"],
      short: "Container runtime packaging complex genomics suites such as DeepVariant or PharmCAT with their exact Linux libraries.",
      more: "Pulling a tool image downloads several gigabytes once from a public registry so local runs execute reproducibly afterward.", learn: "learn-files.html#computing" },
    pixi: { term: "Pixi environment", aliases: ["Pixi", "pixi environment"],
      short: "Isolated folder of version-pinned bioinformatics binaries (such as samtools, bcftools and minimap2) managed by Pixi.",
      more: "Keeps command-line tool versions consistent across machines; WGS Extract checks installed binaries before launching a job.", learn: "learn-files.html#computing" },
    liftover: { term: "Liftover", aliases: ["liftover", "liftOver"],
      short: "Remapping VCF or marker coordinates from one reference build to another (such as GRCh37 to GRCh38) via a chain file.",
      more: "Finishes in minutes on tabular files, while dropping sites in rebuilt gaps that full read realignment can place cleanly.", learn: "learn-reference.html#liftover" },
    chain: { term: "Chain file", aliases: ["chain file", "chain files"],
      short: "Alignment map pairing matching coordinate blocks and gaps from a specific source build to a target build.",
      more: "Directional: lifting GRCh37 to GRCh38 uses a distinct chain file from lifting GRCh38 back to GRCh37.", learn: "learn-reference.html#liftover" },
    rna: { term: "RNA", full: "Ribonucleic acid", aliases: [],
      short: "Single-stranded molecule copied from active genes to carry protein instructions or perform regulatory work in cells.",
      more: "Whole-genome DNA sequencing predicts how variants alter RNA transcripts computationally without measuring live tissue expression.", learn: "learn-dna.html#genes" },
    transcript: { term: "Transcript", aliases: ["transcript", "transcripts"],
      short: "Specific spliced RNA version produced from a gene; one human gene often makes several alternate transcripts.",
      more: "Clinical reports cite versioned identifiers (such as MANE Select transcripts) because exon numbering changes across isoforms.", learn: "learn-health.html#annotation" },
    splicing: { term: "Splicing", aliases: ["splicing", "splice site", "splice sites"],
      short: "Cellular editing step that cuts non-coding introns out of freshly copied RNA and stitches coding exons together.",
      more: "Variants near exon-intron borders or deeper inside introns can skip an exon or shift the reading frame.", learn: "learn-health.html#scores" },
    frameshift: { term: "Frameshift", aliases: ["frameshift"],
      short: "Coding insertion or deletion whose length is indivisible by three, scrambling every three-letter amino-acid codon downstream.",
      more: "Frequently triggers early stop codons and RNA decay, though insertions near the very tail of a transcript can leave most of the protein intact.", learn: "learn-health.html#annotation" },
    recessive: { term: "Recessive", aliases: ["recessive", "carrier", "compound heterozygous"],
      short: "Inheritance pattern where a condition appears only when both parental copies of an autosomal gene carry loss-of-function variants.",
      more: "Someone with one affected copy (0/1) is typically an unaffected carrier; carrying two different pathogenic variants on opposite copies is called compound heterozygosity.", learn: "learn-health.html#clinvar" },
    penetrance: { term: "Penetrance", aliases: ["penetrance"],
      short: "Share of people carrying a given variant genotype who actually develop the associated medical condition.",
      more: "Many clinically tracked variants show incomplete or age-dependent penetrance, where carriers remain healthy or develop signs later in life.", learn: "learn-health.html#clinvar" },
    mosaicism: { term: "Mosaicism", aliases: ["mosaicism", "mosaic"],
      short: "Presence of two genetically distinct cell lineages in one individual arising from a mutation after fertilization.",
      more: "Shows up as skewed allele fractions (for instance 15% of reads instead of 50%) and can differ between blood, saliva and other tissues.", learn: "learn-variants.html#confidence" },
    par: { term: "PAR", full: "Pseudoautosomal region", aliases: ["pseudoautosomal", "pseudoautosomal regions"],
      short: "Matching tips shared by the X and Y chromosomes where the two pair up and swap segments just like autosomes.",
      more: "XY individuals carry two copies across PAR1 and PAR2 alongside single-copy X and Y elsewhere, so callers switch ploidy at build-specific PAR borders.", learn: "learn-variants.html#genotype" },
    adapter: { term: "Adapter", aliases: ["adapter", "adapters"],
      short: "Synthetic DNA oligonucleotide ligated onto fragment ends during library prep so molecules bind to the flow cell.",
      more: "When a DNA insert is shorter than the read length, the sequencer reads past the sample into the adapter tail, which tools like fastp trim off.", learn: "learn-sequencing.html#quality" },
    duplicate: { term: "Duplicate reads", aliases: ["duplicate reads", "duplicates"],
      short: "Multiple read pairs starting and ending at identical coordinates that likely came from PCR copies of one original DNA molecule.",
      more: "Marking duplicates prevents variant callers from counting ten copies of a single PCR error as ten independent molecules.", learn: "learn-sequencing.html#depth" },
    basecalling: { term: "Basecalling", aliases: ["basecalling", "basecaller", "basecalling model"],
      short: "Translating raw optical images or nanopore electrical traces from a sequencer into A, C, G, T read strings and quality scores.",
      more: "Illumina instruments usually basecall onboard to emit FASTQ, whereas Nanopore users can re-basecall archived POD5 files as Dorado models improve.", learn: "learn-sequencing.html#sample" },
    freebayes: { term: "FreeBayes", aliases: [],
      short: "Haplotype-based Bayesian variant caller that evaluates short multi-base alleles directly across aligned BAM or CRAM reads.",
      more: "Useful as a lightweight local caller or second opinion alongside DeepVariant and bcftools.", learn: "learn-files.html#calling" },
    clair3: { term: "Clair3", aliases: [],
      short: "Fast pileup-and-full-alignment neural-network caller built for Oxford Nanopore and PacBio long-read small variants.",
      more: "Pair Clair3 with the model profile matching your exact Nanopore chemistry or HiFi read set.", learn: "learn-files.html#calling" },
    fastqc: { term: "FastQC", full: "FASTQ Quality Control", aliases: ["MultiQC", "fastp"],
      short: "Quality-check program plotting per-cycle base scores, GC distribution, adapter tails and sequence duplication across FASTQ reads.",
      more: "Traffic-light warnings highlight patterns worth checking against your library type before spending hours on alignment.", learn: "learn-sequencing.html#quality" },
    smn: { term: "SMN1 / SMN2", full: "Survival of motor neuron 1 / 2", aliases: ["SMN1", "SMN2"],
      short: "Nearly identical neighbor genes on chromosome 5 where biallelic SMN1 loss causes spinal muscular atrophy.",
      more: "Standard short-read callers struggle to tell SMN1 reads apart from paralog SMN2 or detect silent 2+0 carrier states without specialized copy-number callers and clinical testing.", learn: "learn-health.html#medicines" },
    checksum: { term: "Checksum", aliases: ["checksum", "checksums", "SHA-256", "MD5"],
      full: "SHA-256: Secure Hash Algorithm 256-bit; MD5: Message-Digest Algorithm 5",
      short: "Fixed-length fingerprint computed from file bytes (such as SHA-256) or contig bases (MD5) to catch truncated downloads and mismatched references.",
      more: "CRAM headers embed an MD5 digest for every reference chromosome so decoders halt immediately if handed the wrong FASTA.", learn: "learn-reference.html#cram" },
    bcf: { term: "BCF", full: "Binary Call Format", aliases: [],
      short: "Compact binary counterpart to VCF that bcftools parses and filters much faster than plain text.",
      more: "Converts losslessly back and forth with VCF while keeping identical genotypes and annotations.", learn: "learn-files.html#vcf" },
    tsv: { term: "TSV", full: "Tab-separated values", aliases: [],
      short: "Plain-text table separating columns with tab characters, used for marker kits and exported variant summaries.",
      more: "Keep an unedited copy before opening TSV exports in spreadsheet apps, which famously auto-convert gene symbols like MARCH1 or SEPT2 into calendar dates.", learn: "learn-files.html#reference" },
    parquet: { term: "Parquet", aliases: [],
      short: "Compressed columnar data file built for fast filtering and aggregation across millions of variant or annotation rows.",
      more: "Read directly by DuckDB, Polars, Python and WGS Extract report engines using a fraction of TSV disk space.", learn: "learn-files.html#reference" },
    json: { term: "JSON", full: "JavaScript Object Notation", aliases: [],
      short: "Structured text format storing nested key-value records for run manifests, QC metrics and configuration.",
      more: "Records exact tool versions, checksums and summary numbers alongside the genome files produced by a run.", learn: "learn-files.html#reference" },
    ssd: { term: "SSD", full: "Solid-state drive", aliases: ["SSDs"],
      short: "Flash-based storage drive delivering fast random reads and writes without moving platters.",
      more: "Sorting a 30× alignment writes tens of gigabytes of temporary spill files, finishing far faster on a local SSD than over spinning disks or network shares.", learn: "learn-files.html#computing" },
    qc: { term: "QC", full: "Quality control", aliases: [],
      short: "Upfront checks on read quality, mean depth, sex-chromosome ploidy, Ti/Tv ratio and cross-sample contamination.",
      more: "Catches truncated downloads, mislabelled references and sample swaps before you trust downstream ancestry or health screens.", learn: "learn-sequencing.html#quality" },
    acmgsf: { term: "ACMG SF", full: "American College of Medical Genetics and Genomics Secondary Findings", aliases: ["secondary findings"],
      short: "Curated list of several dozen medically actionable genes (such as BRCA1, LDLR and MLH1) checked during clinical exome or genome sequencing.",
      more: "Updated periodically by ACMG with specific reporting rules per gene; screen hits in personal software still require accredited clinical confirmation.", learn: "learn-health.html#clinvar" },
    cpic: { term: "CPIC", full: "Clinical Pharmacogenetics Implementation Consortium", aliases: [],
      short: "International consortium publishing peer-reviewed drug-dosing tables for validated pharmacogenetic diplotypes.",
      more: "Designed to help clinicians use existing validated lab genotypes when prescribing, alongside clinical judgement.", learn: "learn-health.html#medicines" },
    amp: { term: "AMP", full: "Association for Molecular Pathology", aliases: [],
      short: "Clinical pathology society that co-authored the standard 2015 ACMG/AMP variant-classification guidelines.",
      more: "Clinical geneticists combine population, segregation, functional and computational lines of evidence under this framework rather than relying on automated rules alone.", learn: "learn-health.html#clinvar" },
    stopgained: { term: "Stop-gained", aliases: ["stop-gained", "nonsense"],
      short: "Single-base coding change (also called a nonsense variant) that turns an amino-acid codon into an early stop signal.",
      more: "Often triggers nonsense-mediated RNA decay or truncates the protein, though impact depends on which exon and transcript are affected and whether the gene tolerates losing one copy.", learn: "learn-health.html#annotation" },
  };
  Object.keys(terms).forEach(function (key) {
    if (!terms[key].learn) terms[key].learn = "learn.html#term-" + key;
  });
  WGSM.v2terms.terms = terms;
})();
